{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "plan@1",
  "title": "Plan",
  "description": "A sequenced implementation plan. Every task is bite-sized, with an implementation approach, exact code, the tests proving each criterion, and a commit message.",
  "type": "object",
  "required": ["goal", "architecture", "tech_stack", "tasks"],
  "additionalProperties": false,
  "properties": {
    "goal": {
      "type": "string",
      "description": "One sentence: what this plan produces"
    },
    "architecture": {
      "type": "string",
      "description": "2-3 sentences on the implementation approach"
    },
    "tech_stack": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Key libraries, frameworks, or runtimes involved"
    },
    "tasks": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["id", "title", "files", "steps", "commit_message"],
        "additionalProperties": false,
        "properties": {
          "id": { "type": "string" },
          "title": { "type": "string" },
          "files": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "create": { "type": "array", "items": { "type": "string" } },
              "modify": { "type": "array", "items": { "type": "string" } },
              "test": { "type": "array", "items": { "type": "string" } }
            }
          },
          "steps": {
            "type": "array",
            "minItems": 1,
            "items": { "type": "string" },
            "description": "Ordered steps. Each step is one action. Code steps include exact code. Test steps include exact command and expected output."
          },
          "commit_message": {
            "type": "string",
            "description": "Conventional commit message for this task"
          },
          "depends_on": {
            "type": "array",
            "items": { "type": "string" },
            "description": "IDs of tasks that must complete before this one"
          },
          "covers_criteria": {
            "type": "array",
            "items": { "type": "string" },
            "description": "IDs of acceptance criteria from spec@1 that this task covers. challenger checks that every criterion ID appears in at least one task."
          }
        }
      }
    },
    "batches": {
      "type": "array",
      "description": "Optional grouping of tasks into cohesive subsystem/crate compilation units to allow batch execution and minimize subagent spawns.",
      "items": {
        "type": "object",
        "required": ["batch_id", "title", "target_crate", "task_ids"],
        "additionalProperties": false,
        "properties": {
          "batch_id": { "type": "string" },
          "title": { "type": "string" },
          "target_crate": { "type": "string" },
          "task_ids": { "type": "array", "items": { "type": "string" } }
        }
      }
    },
    "linked_spec": {
      "type": "string",
      "description": "ID of the spec@1 this plan implements"
    },
    "spec_file_path": {
      "type": "string",
      "description": "Workspace-relative path to the spec@1 file this plan implements (e.g. docs/specs/SPEC-001.json). Propagated from spec@1.spec_file_path. Agents resolve it against workspace_root from the recon manifest."
    },
    "plan_file_path": {
      "type": "string",
      "description": "Workspace-relative path where this plan is written on disk (e.g. docs/projects/SPEC-001.json), keyed by linked_spec. Set by the navigator skill orchestrator after challenger passes. Agents resolve it against workspace_root from the recon manifest."
    },
    "spec_hash": {
      "type": "string",
      "description": "Content hash (e.g. sha256:<hex>) of the spec@1 file at spec_file_path as it existed when this plan was created. Set by planner. recon recomputes the current file's hash and compares it to this value to detect whether the spec changed after planning — a mismatch means the plan may not cover criteria added or changed since it was made."
    },
    "linked_requirement": {
      "type": "string",
      "description": "ID of the requirement@1 the source spec@1 implements. Propagated from spec@1.linked_requirement by planner so the full requirement-to-code chain is traceable without re-reading the spec."
    },
    "reasoning": {
      "type": "string",
      "description": "Agent scratchpad — not consumed downstream"
    }
  }
}
{
  "id": "SPEC-RELEASE-ORCHESTRATION-003",
  "purpose": "Define a fast, single-approval GitHub workflow that builds and executes the immutable Callisto product release, supports exact historical recovery on fresh runners, and proves the complete path in an isolated rehearsal before production.",
  "scope": "Release pull request authorization, GitHub Actions jobs and permissions, plan and artifact handoffs, four-target build fan-out, manual historical recovery, removal of the Environment approval, staging-rehearsal topology and failpoints, and retirement of superseded pre-v1 release routes.",
  "non_goals": [
    "A second human approval after the release pull request is merged.",
    "Using GitHub Actions cache, runner-local paths, mutable branches, or workflow output booleans as release authority.",
    "Publishing a rehearsal artifact to crates.io, npmjs.com, production PyPI, or the production Callisto GitHub Release namespace.",
    "Apple Developer ID signing or notarization.",
    "Preserving compatibility for pre-v1 release commands, workflow layouts, state files, or per-package GitHub release behavior."
  ],
  "api_surface": [
    {
      "name": "release workflow dispatch inputs",
      "signature": "workflow_dispatch { release_commit?: full CommitSha, source_run_id?: GitHubRunId, intent_digest?: IntentDigest, artifact_manifest_digest?: ArtifactDigest }",
      "description": "An explicit recovery route that either runs the newly merged release commit or retrieves the exact intent and build handoff from a prior run, then independently validates every binding before credentials are exposed.",
      "error_conditions": [
        "A recovery input is partial, malformed, expired, belongs to another repository, or does not bind the exact release commit and intent digest.",
        "The selected commit is not a verified merge of the managed release pull request."
      ]
    },
    {
      "name": "release rehearsal workflow",
      "signature": "rehearse-release(release_commit, failpoint?)",
      "description": "A reusable workflow invocation against an isolated GitHub repository and non-production registry endpoints that runs the same planning, build, attestation, execution, observation, and receipt boundaries as production.",
      "error_conditions": [
        "Any production registry endpoint, production tag namespace, or production release repository is selected.",
        "A configured interruption fails to resume on a new job/run and converge."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "The reviewed managed release pull request merge is the sole human approval event. The production workflow contains no environment-policy job, required-reviewer API check, protected Environment reviewer gate, or second manual approval; merge automatically proceeds through plan, build, attest, execute, and final verify when checks pass.",
      "is_error_case": false
    },
    {
      "id": "AC-002",
      "criterion": "The automatic path proves that the triggering commit is exactly one verified merge of the canonical managed release branch, then invokes the provider-neutral callisto release planner to derive and validate the immutable intent from that merge and its reviewed decision. Workflow verifies eligibility and transports files but never constructs operations, tags, package rosters, targets, or artifact names; direct pushes, unrelated pull requests, ambiguous merges, mutable branch tips, and mismatched intent/source fail.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "Planning has read-only repository permission and no release credentials. Build jobs have only source-read plus attestation/OIDC permissions. A separate read-only validation job validates the intent, source commit, complete artifact manifest, bytes, checksums, and attestations before execute starts. The execute job has job-scoped contents-write permission, repeats validation, and exposes registry secrets only to the final CLI invocation. Removing the Environment gate does not widen any earlier job's permissions.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "The build stage obtains a total matrix from the CLI's validated immutable intent and maps every declared slot exactly once; an unknown, missing, extra, or workflow-defaulted slot fails before build. It produces the aarch64-apple-darwin, x86_64-unknown-linux-musl, aarch64-unknown-linux-musl, and wasm32-wasip1 payloads plus all registry-package artifacts. A fan-in job validates the complete slot roster, creates deterministic archives and SHA256SUMS, records the artifact manifest, and ensures each required file has a GitHub attestation before execution can start.",
      "is_error_case": true
    },
    {
      "id": "AC-005",
      "criterion": "Intent, artifact-manifest, metadata, and receipt handoffs use strict model schemas, while payload/checksum bytes are validated by those schemas; all are downloaded outside the trusted source checkout and retained for a documented recovery window of at least seven days. Retention grants no authority: CLI revalidates every byte and identifier against the immutable intent, source commit, and original artifact-manifest digest. After expiry, a rebuild is usable only if it reproduces every original digest; otherwise recovery fails with an unrecoverable-handoff diagnostic rather than minting replacement expected bytes.",
      "is_error_case": false
    },
    {
      "id": "AC-006",
      "criterion": "A workflow_dispatch recovery can name an exact historical full release commit and either reproduce the original artifact-manifest digests or consume a named prior run whose intent and artifact-manifest digests are supplied. It verifies the original managed-PR merge, plan digest, source commit, artifact bindings, and original artifact identity, then uses external-state convergence; it never substitutes current main, latest, a different run's artifacts, newly chosen expected bytes, or runner-local state.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "The execute job invokes the core CLI once with the exact intent, artifact manifest, artifact directory, state path, and receipt path. Workflow shell does not publish registries, derive tag names, create releases, upload product assets, classify already-present responses, or decide completion independently of the CLI.",
      "is_error_case": false
    },
    {
      "id": "AC-008",
      "criterion": "The release workflow fails unless the CLI emits and the workflow validates a complete receipt for the same intent digest. The receipt and complete observation report are uploaded even on failure when safely available; a green execute or workflow conclusion without a valid complete receipt is impossible.",
      "is_error_case": true
    },
    {
      "id": "AC-009",
      "criterion": "The isolated rehearsal uses a dedicated non-production GitHub repository or equivalent isolated forge namespace plus non-production Cargo, npm, and PyPI registry endpoints and credentials. Repository and endpoint selection is resolved by graph before intent derivation and captured in typed intent/prepared bindings; workflow allowlists credentials and environment but cannot override those identities afterward. Allowlists fail closed before production registries, the production repository, or a production callisto@X.Y.Z tag can be addressed.",
      "is_error_case": true
    },
    {
      "id": "AC-010",
      "criterion": "One rehearsal covers managed release-PR merge, immutable plan, every real Callisto registry artifact build, all four product builds and native/WASM smoke tests, checksums, GitHub attestations, product tag, prepared release, asset uploads, final release publication, final observation, and receipt without production credentials. Separate representative npm and PyPI fixtures run through the same production adapters, including per-file interruption, exact rerun, digest conflict, and unverifiable-metadata cases even though Callisto itself currently publishes only Cargo packages.",
      "is_error_case": false
    },
    {
      "id": "AC-011",
      "criterion": "Rehearsal failpoints can stop after each provider mutation and before each following journal or receipt write. Each failpoint is resumed in a fresh job or run without its predecessor's RUNNER_TEMP state, and the second run must converge without duplicate mutation or false success. Conflict, unverifiable, expired-handoff, and wrong-source negative cases must also fail with actionable diagnostics.",
      "is_error_case": true
    },
    {
      "id": "AC-012",
      "criterion": "A proposed release-boundary implementation may be developed only in the isolated branch/rehearsal path and cannot be activated against production or used for the first production release until that exact candidate revision passes the full rehearsal suite. Later changes to release intent schemas, provider adapters, operation DAG, build matrix, attestation policy, or workflow handoff contract rerun the rehearsal gate before production activation.",
      "is_error_case": true
    },
    {
      "id": "AC-013",
      "criterion": "Superseded pre-v1 effect routes `plan-publish`, `publish`, `tag --plan`, and `filter-plan` are removed as independent release paths, along with their contradictory documentation. The `version`, changeset, status, matrix, and other non-effect capabilities required to prepare the release pull request remain. Any retained preview delegates to the canonical release planner and cannot publish, tag, upload, or create a release. There is one release plan/inspect/reconcile/execute family, one release-PR action, and one product-release workflow, with no Environment-gated, journal-authoritative, per-package GitHub release, or shell-owned effect path.",
      "is_error_case": false
    },
    {
      "id": "AC-014",
      "criterion": "All third-party Actions remain pinned to immutable commit SHAs; concurrency consumes a CLI-validated canonical ProductReleaseId and repository identity rather than reconstructing a tag in YAML; logs and uploaded diagnostics contain no credentials; and every shell interpolation crossing from workflow inputs is passed through a named environment variable and validated before use.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-RELEASE-ORCHESTRATION-003.json",
  "revision_note": "Supersedes the required-reviewer Environment and compatibility-window criteria in .claude/specs/SPEC-RELEASE-INTERFACES-013.json and related draft release specifications, based on the user's explicit pre-v1 product decisions.",
  "reasoning": "The rehearsal is not another approval gate. It is automated evidence that the same production boundaries work across real job isolation, provider protocols, attestations, and interruption. Thirty-day handoff retention supports recovery while the core still treats only the validated intent, artifact bytes, and observed provider state as authority."
}
{
  "goal": "Produce one immutable, least-privilege Callisto release workflow and isolated rehearsal that can execute or exactly recover a reviewed product release while proving complete external convergence.",
  "architecture": "Extend the existing model/graph release boundary with strict, versioned handoff, artifact, observation, and receipt contracts; keep planning provider-neutral and make graph-owned convergence the sole effect authority. Replace the current push/environment-gated workflow with a merge-verified plan/build/attest/validate/execute/final-verify topology, and exercise the same boundaries in a failpoint-driven isolated rehearsal. Retire pre-v1 effect commands and documentation after the canonical release family is complete.",
  "tech_stack": [
    "Rust workspace crates callisto-model, callisto-graph, and callisto-cli",
    "serde, schemars, sha2, miette, and callisto_model::atomic::atomic_write",
    "GitHub Actions YAML with immutable action commit SHAs and OIDC artifact attestations",
    "GitHub CLI/API, Cargo, npm/pnpm, twine/PyPI-compatible fixtures, and Bash contract tests",
    "just and moon task runners"
  ],
  "linked_spec": "SPEC-RELEASE-ORCHESTRATION-003",
  "spec_file_path": "docs/specs/SPEC-RELEASE-ORCHESTRATION-003.json",
  "plan_file_path": "docs/projects/SPEC-RELEASE-ORCHESTRATION-003.json",
  "spec_hash": "sha256:111cf1ca8a6a8820ee21289ddaa5b7a7a91da290adf5195ac1a3fe6b9b1e98ab",
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "reasoning": "Planning evidence: .github/workflows/callisto-release.yml currently has push-triggered versioning, an environment-policy reviewer job, one-day artifact retention, no fan-out matrix, no receipt/final-verify boundary, and runner-local execution state. The live model already contains ReleaseIntentV1, ArtifactManifestV1, artifact attestation policy, prepared operations, and atomic state storage, while graph execution still needs the convergence/receipt contract. Cross-spec blocker: SPEC-RELEASE-CONVERGENCE-002 is a prerequisite for the observation report, provider convergence semantics, receipt store, and interruption guarantees used by AC-007, AC-008, and AC-011; orchestration must not activate production until that spec's implementation and gate pass. Cross-spec alignment must also be checked against SPEC-RELEASE-PRODUCT-MODEL-001 for the canonical ProductReleaseId and four target slots, and SPEC-RELEASE-WORKSPACE-MEMBERSHIP-AUTHORITY-004 for package exclusion/authority. Re-run the full rehearsal gate after any change to those contracts, provider adapters, operation DAG, matrix, attestations, or handoffs."
  ,"tasks": [
    {
      "id": "T001",
      "title": "Establish strict release handoff, observation, receipt, and recovery models",
      "files": {
        "modify": [
          "crates/callisto-model/src/release.rs",
          "crates/callisto-model/src/lib.rs",
          "crates/callisto-model/src/error.rs"
        ],
        "create": [
          "crates/callisto-model/tests/release_handoff_schema_tests.rs"
        ],
        "test": [
          "crates/callisto-model/tests/release_handoff_schema_tests.rs"
        ]
      },
      "steps": [
        "Read SPEC-RELEASE-CONVERGENCE-002 and SPEC-RELEASE-PRODUCT-MODEL-001 before changing shared types; record their exact field/version dependencies in the Rust module docs.",
        "Add versioned serde/schemars types for IntentHandoff, ArtifactManifest handoff digest/retention metadata, ReleaseObservationEvidence, ReleaseReceipt, prepared provider bindings, and recovery identity; bind every type to IntentDigest, source CommitSha, repository identity, and canonical ProductReleaseId.",
        "Make constructors and custom deserializers reject duplicate/missing/extra slots, mismatched digests, wrong source commits, production rehearsal identities, malformed repository/registry identities, and receipts that are not complete terminal observations; derive miette-compatible typed errors with actionable recovery guidance.",
        "Ensure all receipt and state persistence uses callisto_model::atomic::atomic_write and that no schema treats a journal, workflow output, or receipt alone as external authority.",
        "Run `cargo nextest run -p callisto-model --all-features --test release_handoff_schema_tests` and `cargo test -p callisto-model --doc --all-features`; expect all tests to pass and malformed fixtures to report the named diagnostic code."
      ],
      "commit_message": "feat(model): define strict release handoff and receipt contracts",
      "covers_criteria": ["AC-005", "AC-008", "AC-009", "AC-011", "AC-014"]
    },
    {
      "id": "T002",
      "title": "Derive canonical product intent and complete four-target artifact roster",
      "files": {
        "modify": [
          "crates/callisto-graph/src/commands/release.rs",
          "crates/callisto-graph/src/commands/release_decision.rs",
          "crates/callisto-graph/src/commands/release_artifacts.rs",
          "crates/callisto-graph/src/error.rs",
          "crates/callisto-model/src/release.rs"
        ],
        "create": [
          "crates/callisto-graph/tests/product_release_intent_tests.rs"
        ],
        "test": [
          "crates/callisto-graph/tests/product_release_intent_tests.rs"
        ]
      },
      "steps": [
        "Change release derivation to accept only one verified merge of the canonical managed release branch/PR, bind the reviewed .callisto/release-decision.json, and reject direct pushes, unrelated/ambiguous PRs, mutable tips, stale decisions, and source/intent mismatches before constructing operations.",
        "Implement one canonical ProductReleaseId/tag identity and one product-level operation DAG; exclude callisto-fixtures and remove package-derived GitHub release/tag identities while retaining registry package entries required by the decision.",
        "Derive the total artifact matrix from validated immutable intent with exactly aarch64-apple-darwin, x86_64-unknown-linux-musl, aarch64-unknown-linux-musl, and wasm32-wasip1 plus every declared registry-package artifact; reject unknown, missing, duplicate, extra, or workflow-defaulted slots.",
        "Construct ArtifactUpload operations and strict ArtifactManifestV1 entries with deterministic archive names, sizes, SHA256 digests, source commit, intent digest, repository/workflow/commit attestation policy, and complete roster validation.",
        "Run `cargo nextest run -p callisto-graph --all-features --test product_release_intent_tests`; run `cargo nextest run -p callisto-graph --all-features --test matrix_tests --test durable_release_e2e_tests` and expect canonical identity, exclusion, roster, and negative provenance cases to pass."
      ],
      "commit_message": "feat(graph): derive immutable product release and artifact roster",
      "depends_on": ["T001"],
      "covers_criteria": ["AC-002", "AC-004", "AC-009", "AC-013"]
    },
    {
      "id": "T003",
      "title": "Implement provider observation, convergence, and complete receipt emission",
      "files": {
        "modify": [
          "crates/callisto-graph/src/commands/release.rs",
          "crates/callisto-graph/src/commands/release_execution.rs",
          "crates/callisto-graph/src/commands/release_store.rs",
          "crates/callisto-graph/src/commands/release_artifacts.rs",
          "crates/callisto-graph/src/error.rs"
        ],
        "create": [
          "crates/callisto-graph/tests/release_convergence_recovery_tests.rs"
        ],
        "test": [
          "crates/callisto-graph/tests/release_convergence_recovery_tests.rs"
        ]
      },
      "steps": [
        "Block this task until SPEC-RELEASE-CONVERGENCE-002 implementation is merged and its gate passes; import its graph-private observation boundary rather than duplicating provider probing or journal authority.",
        "For every canonical operation, observe exact/absent/incomplete/conflict/unverifiable state before mutation, mutate only verified missing work, re-observe postconditions, and persist diagnostic state atomically; never classify a successful subprocess exit as a receipt.",
        "Add artifact upload, tag, registry, and forge-release provider adapters that use typed prepared bindings, exact digest/identity matching, and one invocation-scoped operation DAG; keep credentials unavailable to planning, validation, and build code.",
        "Emit and atomically persist a ReleaseReceipt only after a complete final observation proves every intended operation exact; return nonzero with operation and recovery diagnostics for any incomplete state, conflict, unverifiable provider, missing receipt, or receipt-write failure.",
        "Add failpoint seams after each provider mutation and before each following journal/receipt write; run `cargo nextest run -p callisto-graph --all-features --test release_convergence_recovery_tests` and `cargo nextest run -p callisto-graph --all-features --test durable_release_e2e_tests`, expecting fresh-runner reruns to converge without duplicate effects."
      ],
      "commit_message": "feat(graph): converge release effects and emit verified receipts",
      "depends_on": ["T001", "T002"],
      "covers_criteria": ["AC-005", "AC-006", "AC-007", "AC-008", "AC-011"]
    },
    {
      "id": "T004",
      "title": "Expose exact recovery and inspect/validate CLI boundaries",
      "files": {
        "modify": [
          "crates/callisto-cli/src/cli.rs",
          "crates/callisto-cli/src/commands/release.rs",
          "crates/callisto-cli/src/commands/schema.rs",
          "crates/callisto-cli/src/error.rs"
        ],
        "create": [
          "crates/callisto-cli/tests/release_recovery_cli_tests.rs"
        ],
        "test": [
          "crates/callisto-cli/tests/release_recovery_cli_tests.rs"
        ]
      },
      "steps": [
        "Add workflow-dispatch recovery arguments for exact full release commit, prior source run ID, intent digest, and artifact-manifest digest; reject partial, malformed, expired, cross-repository, wrong-source, wrong-PR, and mismatched-digest combinations before credentialed execution.",
        "Add strict `release validate`/`release receipt` or equivalent machine-readable validation paths that verify intent, artifact manifest, bytes, checksums, attestations, source commit, plan digest, and complete receipt without recomputation or mutable branch lookup.",
        "Make `release execute` accept exactly intent, artifact manifest, artifact directory, state path, and receipt path, invoke graph convergence once, and fail unless the returned receipt is complete and bound to the exact intent digest; write diagnostics without secrets.",
        "Update schema output and miette error cards so recovery errors identify the rejected binding and the safe next action; retain `release inspect`, `reconcile`, `version`, changeset, status, and matrix capabilities.",
        "Run `cargo nextest run -p callisto-cli --all-features --test release_recovery_cli_tests --test durable_release_e2e_tests` and `cargo test -p callisto-cli --doc --all-features`; expect exact historical recovery and all invalid-input cases to fail closed."
      ],
      "commit_message": "feat(cli): add exact historical recovery and receipt validation",
      "depends_on": ["T003"],
      "covers_criteria": ["AC-005", "AC-006", "AC-007", "AC-008", "AC-014"]
    },
    {
      "id": "T005",
      "title": "Build deterministic four-target artifacts with attestations and retained handoffs",
      "files": {
        "modify": [
          ".github/workflows/callisto-release.yml",
          "Justfile",
          ".github/tests/verify-release-workflow-contract.sh"
        ],
        "create": [
          ".github/actions/build-release-artifacts/action.yml",
          ".github/actions/build-release-artifacts/scripts/build-matrix.sh",
          ".github/actions/build-release-artifacts/scripts/write-manifest.sh",
          ".github/actions/build-release-artifacts/tests/test_build_matrix_contract.sh"
        ],
        "test": [
          ".github/actions/build-release-artifacts/tests/test_build_matrix_contract.sh"
        ]
      },
      "steps": [
        "Replace workflow-defaulted build behavior with a CLI-produced JSON matrix; validate exact slot equality before fan-out and fail before any build when a slot is unknown, missing, duplicate, extra, or absent from intent.",
        "Build aarch64-apple-darwin, x86_64-unknown-linux-musl, aarch64-unknown-linux-musl, wasm32-wasip1, and every registry-package artifact from the checked-out source commit; run native and WASM smoke tests and place outputs under an explicit artifact directory outside the trusted checkout handoff.",
        "Fan in all matrix outputs, create deterministic archives and SHA256SUMS, calculate the strict ArtifactManifestV1, verify every byte and checksum, and require a GitHub build attestation for every required file before upload.",
        "Upload intent, artifact manifest, metadata, checksums, and payloads with retention-days at least 7 (document the recovery window); download them only under runner.temp and never use cache, runner-local state, or workflow output booleans as authority.",
        "Run `bash .github/actions/build-release-artifacts/tests/test_build_matrix_contract.sh`, `bash .github/tests/verify-release-workflow-contract.sh`, `just fmt-check`, and `just lint`; expect exact matrix/retention/attestation assertions and clean formatting/lints."
      ],
      "commit_message": "feat(ci): build and attest deterministic release artifacts",
      "depends_on": ["T002", "T004"],
      "covers_criteria": ["AC-003", "AC-004", "AC-005", "AC-014"]
    },
    {
      "id": "T006",
      "title": "Replace production workflow with one merge-approved least-privilege path",
      "files": {
        "modify": [
          ".github/workflows/callisto-release.yml",
          ".github/tests/verify-release-workflow-contract.sh",
          ".github/tests/verify-action-pins.sh",
          ".github/CODEOWNERS"
        ],
        "test": [
          ".github/tests/verify-release-workflow-contract.sh",
          ".github/tests/verify-action-pins.sh"
        ]
      },
      "steps": [
        "Change triggers to the canonical managed release-PR merge plus explicit workflow_dispatch recovery inputs; prove exactly one verified merge and bind repository identity, full commit SHA, reviewed decision, plan digest, intent digest, and artifact-manifest digest before any credential exposure.",
