        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--package",
            "cargo/demo",
            "--from-release-commit",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "--out",
            "intent.json",
        ])
        .is_err());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--from-release-commit",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "--out",
            "intent.json",
        ])
        .is_err());
        assert!(Cli::try_parse_from([
            "callisto",
            "release",
            "plan",
            "--from-release-commit",
            "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            "--decision",
            "release-decision.json",
            "--out",
            "intent.json",
        ])
        .is_ok());
    }

